import{_ as d,C as a,o as c,c as l,a2 as t,E as r,w as s,j as i}from"./chunks/framework.C2TvIV46.js";const f=JSON.parse('{"title":"オブジェクトリスト","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/object-lists.md","filePath":"ja/language/object-lists.md"}'),n={name:"ja/language/object-lists.md"};function _(g,e,b,p,m,h){const o=a("DocsBlock");return c(),l("div",null,[e[1]||(e[1]=t('<h1 id="オブジェクトリスト" tabindex="-1">オブジェクトリスト <a class="header-anchor" href="#オブジェクトリスト" aria-label="Permalink to &quot;オブジェクトリスト&quot;">​</a></h1><p>Reach は Megalo スクリプトの隣に、プレーンテキストの <strong>オブジェクトリスト</strong> フォルダを同梱しています。既定の Halo Reach Editing Kit (HREK) インストールでは次にあります。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/multiplayer/megalo/object_lists/</span></span></code></pre></div><p>（Steam 下では例として <code>…/HREK/data/multiplayer/megalo/object_lists/</code>）。</p><p>Bungie の Megalo エディタ（<strong>MegaloEdit</strong>）は、オートコンプリート、構文ヘルプ、<strong>Help</strong> メニューの参照一覧のためにこれらのファイルを読み込みます。ゲームエンジンも同じテーブルを使い、ゲームタイプやカスタムバリアントのコンパイル時にスクリプト内の記号名を数値インデックスへ変換します。</p><p>これらのリストは <code>loadout_globals_definition</code>（<code>lgtd</code>）、<code>megalo_string_id_table</code>（<code>msit</code>）、<code>multiplayer_object_type_list</code>（<code>motl</code>）タグ内のデータに対応します。</p>',6)),r(o,{type:"info",title:"カスタムマップ"},{default:s(()=>[...e[0]||(e[0]=[i("p",null,"オブジェクトリストの内容はすべてタグ内のデータに対応します。そのため、標準 Reach コンテンツだけでなく、カスタムオブジェクト、武器、車両、その他マップ固有のエントリを持つカスタムマップ向けに Megalo スクリプトを書けます。",-1)])]),_:1}),e[2]||(e[2]=t('<h2 id="形式" tabindex="-1">形式 <a class="header-anchor" href="#形式" aria-label="Permalink to &quot;形式&quot;">​</a></h2><p>各ファイルは単純な照合テーブルです。</p><ul><li><strong>1 行に 1 エントリ</strong> — 句読点なしの snake_case 識別子。</li><li><strong>行順がインデックス</strong> — 先頭行がインデックス <code>0</code>（下記で注記する場合は id <code>1</code>）。一部のリスト（特に <code>incidents.txt</code>）では空行もエンジン上のインデックス枠を消費します。</li><li><strong>名前は安定した語彙</strong> — Megalo ソースに文字どおり書きます（<code>action create_object warthog …</code>、<code>submit_incident kill</code> など）。</li></ul><p>これらのリストは Megalo スクリプトの要素では <strong>ありません</strong>。スクリプトが名前で参照するエンジンデータです。</p><h2 id="各ファイルの用途" tabindex="-1">各ファイルの用途 <a class="header-anchor" href="#各ファイルの用途" aria-label="Permalink to &quot;各ファイルの用途&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ファイル</th><th>エントリ数</th><th>用途</th><th>タグ</th></tr></thead><tbody><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/objects.txt" target="_blank" rel="noreferrer"><code>objects.txt</code></a></td><td>~220</td><td><strong>マスターオブジェクト型テーブル。</strong> 武器、車両、装備、情景、スポーン地点、Forge オブジェクト、特殊マーカー。<code>create_object</code>、<code>object_matches_filter</code>、リスポーン／車両アクション、<code>map_object</code> の <code>type</code> フィールドが参照。</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/weapons.txt" target="_blank" rel="noreferrer"><code>weapons.txt</code></a></td><td>24</td><td><strong>プレイヤー特性の主／副武器。</strong> 固定順の <code>objects.txt</code> の部分集合。<code>player_traits</code> ブロック（<code>primary_weapon</code>、<code>secondary_weapon</code>）で使用。インデックスはゲームタイプが実際に使うオブジェクト型に対して解決される。</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/equipment.txt" target="_blank" rel="noreferrer"><code>equipment.txt</code></a></td><td>10</td><td><strong>プレイヤー特性の装備スロット。</strong> アーマーアビリティと装備（<code>sprint_equipment</code>、<code>jet_pack_equipment</code>、…）。武器と同じ絶対インデックス規則。</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/vehicles.txt" target="_blank" rel="noreferrer"><code>vehicles.txt</code></a></td><td>34</td><td><strong>車両名</strong> — エディタが車両ピッカーを出す特性／フィルタオペランド用（<code>objects.txt</code> エントリの部分集合）。</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/grenades.txt" target="_blank" rel="noreferrer"><code>grenades.txt</code></a></td><td>4</td><td><strong>手榴弾タイプ</strong> — <code>player_traits</code> の <code>initial_grenades</code>（<code>frag_grenade</code>、<code>plasma_grenade</code>、<code>spike_grenade</code>、<code>firebomb_grenade</code>）。</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/incidents.txt" target="_blank" rel="noreferrer"><code>incidents.txt</code></a></td><td>~470</td><td><strong>ゲームインシデント</strong> — <code>submit_incident</code> と <code>submit_incident_with_custom_value</code> 用。キル、メダル、モードイベント（CTF、KOTH、Infection、…）、サバイバル、実績、アナウンサートリガーをカバー。インシデント id は <strong>1 始まり</strong>（先頭行 = インシデント <code>1</code>）。</td><td><code>globals\\incident.properties.incident_global_properties_definition</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/loadout_palettes.txt" target="_blank" rel="noreferrer"><code>loadout_palettes.txt</code></a></td><td>15</td><td><strong>ロードアウトパレットプリセット</strong> — <code>set_loadout_palette</code> と <code>override loadout_palette</code> 用（<code>slayer_loadouts</code>、<code>objective_loadouts</code>、ファイアファイト用パレットなど）。</td><td><code>multiplayer\\invasion.loadout_globals_definition</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/loadouts.txt" target="_blank" rel="noreferrer"><code>loadouts.txt</code></a></td><td>~80</td><td><strong>ロードアウト表示名</strong>（<code>loadout_name_carter</code>、<code>loadout_name_ninja</code>、…）。アクションオペコードではなく、エディタと UI がロードアウト選択肢を提示するときに使用。</td><td><code>multiplayer\\invasion.loadout_globals_definition</code></td></tr><tr><td><span id="weapon_sets"><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/weapon_sets.txt" target="_blank" rel="noreferrer"><code>weapon_sets.txt</code></a></span></td><td>16</td><td><strong>武器制限プリセット</strong> — <a href="/MegaloEvolved/beta/docs/ja/language/elements/game-options"><code>game_options</code></a> の <code>override weapon_set</code> 用。センチネルトークン（<code>none</code>、<code>default</code>、<code>random</code>）と完全なプリセット一覧は <a href="/MegaloEvolved/beta/docs/ja/language/enums/game-options/weapon-set">Weapon Set</a> を参照。</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><span id="vehicle_sets"><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/vehicle_sets.txt" target="_blank" rel="noreferrer"><code>vehicle_sets.txt</code></a></span></td><td>14</td><td><strong>車両制限プリセット</strong> — <code>override vehicle_set</code> 用（<code>mongoose_only</code>、<code>no_aircraft</code>、<code>all_vehicles</code>、…）。センチネルとインデックスは <a href="/MegaloEvolved/beta/docs/ja/language/enums/game-options/vehicle-set">Vehicle Set</a> を参照。</td><td><code>multiplayer\\globals.multiplayer_object_type_list</code></td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/hud_widget_icons.txt" target="_blank" rel="noreferrer"><code>hud_widget_icons.txt</code></a></td><td>33</td><td><strong>HUD ウィジェットアイコン</strong> — <code>hud_widget_set_icon</code> 用（<code>slayer</code>、<code>ctf</code>、<code>koth</code>、<code>generic_icon_2</code>、…）。このリストの一部の名前（<code>spartan</code> 以降）はゲーム内アイコンと一致しません。後からアイコンが追加されたのにリストが更新されなかったためと思われます。</td><td><code>ui\\chud\\bitmaps\\variant_items\\gametypes.bitmap</code>（このタグがゲーム内表示アイコンを持ちますが、ツールコマンド <code>multiplayer-generate-all-string-lists</code> はリストを更新しないため、手動更新が必要です。このタグは <code>player_set_objective_allegiance_icon</code> で表示されるアイコンにも対応しますが、そのアクションはこのリストを使いません。）</td></tr><tr><td><a href="https://github.com/Blam-Network/megalo/blob/main/src/object_lists/strings.txt" target="_blank" rel="noreferrer"><code>strings.txt</code></a></td><td>~58</td><td><strong>文字列トークン</strong> — <code>device_animate_position</code> および関連デバイスアクション用（<code>mp_boneyard_a_fly_in</code> のようなマップ固有アニメ名）、<code>create_object</code> で使うオブジェクトバリアント（<code>default</code> や <code>carter</code> など）、<code>hs_function_call</code> の関数名（既定では利用可能なものはありません）。</td><td><code>multiplayer\\megalo\\global.megalo_string_id_table</code></td></tr></tbody></table><h2 id="objects-txt-との関係" tabindex="-1"><code>objects.txt</code> との関係 <a class="header-anchor" href="#objects-txt-との関係" aria-label="Permalink to &quot;`objects.txt` との関係&quot;">​</a></h2><p>ほとんどの専門リストはマスター <code>objects.txt</code> テーブルの <strong>部分集合またはビュー</strong> です。</p><ul><li><code>weapons.txt</code> と <code>equipment.txt</code> は <code>objects.txt</code> にもある名前を列挙しますが、プレイヤー特性はゲームタイプが使用とマークしたオブジェクト型に依存する圧縮された <strong>絶対インデックス</strong> で符号化します。</li><li><code>vehicles.txt</code> は車両ピッカー用の便宜リストです。車両型はコンパイル済みデータでは依然として <code>objects.txt</code> インデックス経由で解決されます。</li></ul><p>迷ったら名前が <code>objects.txt</code> にあるか確認してください — それがスポーンとフィルタアクションの正式なオブジェクト型名前空間です。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/">Megalo 言語の概要</a> — これらの名前を消費する <code>map_object</code>、<code>player_traits</code>、アクション</li><li><a href="/MegaloEvolved/beta/docs/ja/versions/">Megalo バージョン</a> — Reach ビルドごとのアクションオペコード</li></ul>',12))])}const j=d(n,[["render",_]]);export{f as __pageData,j as default};
